-- test/fixtures/prod_schema.sql
-- Schema of the app.finman.money PRODUCTION database (lineage without git),
-- captured 2026-10-09 by executing prod db/database.js initDatabase() on a
-- scratch file and dumping sqlite_master (understand/lineage-diff/schema/prod_schema.txt).
-- Used by test/migration-017.test.js: wave2 initDatabase()+migrations must run
-- cleanly on top of this and converge to the same table/column/index sets.
-- Tables first, then indexes. Do not edit by hand.

CREATE TABLE account_permissions ( id INTEGER PRIMARY KEY AUTOINCREMENT, account_id INTEGER NOT NULL, user_id INTEGER NOT NULL, can_view BOOLEAN DEFAULT 1, can_edit BOOLEAN DEFAULT 0, can_delete BOOLEAN DEFAULT 0, can_add_transactions BOOLEAN DEFAULT 0, granted_by INTEGER NOT NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (account_id) REFERENCES accounts (id) ON DELETE CASCADE, FOREIGN KEY (user_id) REFERENCES users (id), FOREIGN KEY (granted_by) REFERENCES users (id), UNIQUE(account_id, user_id) );
CREATE TABLE accounts ( id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, name TEXT NOT NULL, account_number TEXT, bank_name TEXT, currency TEXT DEFAULT 'RUB', balance REAL DEFAULT 0, account_type TEXT, is_active BOOLEAN DEFAULT 1, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users (id) );
CREATE TABLE ai_chat_sessions ( id INTEGER PRIMARY KEY AUTOINCREMENT, org_id INTEGER NOT NULL, user_id INTEGER NOT NULL, session_id TEXT UNIQUE NOT NULL, messages TEXT NOT NULL DEFAULT '[]', created_at DATETIME DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP );
CREATE TABLE ai_insights ( id INTEGER PRIMARY KEY AUTOINCREMENT, org_id INTEGER NOT NULL, user_id INTEGER NOT NULL, period TEXT NOT NULL, type TEXT NOT NULL, content TEXT NOT NULL, model TEXT, generated_at DATETIME DEFAULT CURRENT_TIMESTAMP, UNIQUE(org_id, user_id, period, type) );
CREATE TABLE bank_connections ( id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, bank_id TEXT NOT NULL, access_token TEXT, refresh_token TEXT, expires_at DATETIME, account_ids TEXT, is_active BOOLEAN DEFAULT 1, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users (id) );
CREATE TABLE budget_permissions ( id INTEGER PRIMARY KEY AUTOINCREMENT, budget_id INTEGER NOT NULL, user_id INTEGER NOT NULL, can_view BOOLEAN DEFAULT 1, can_edit BOOLEAN DEFAULT 0, granted_by INTEGER NOT NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (budget_id) REFERENCES budgets (id) ON DELETE CASCADE, FOREIGN KEY (user_id) REFERENCES users (id), FOREIGN KEY (granted_by) REFERENCES users (id), UNIQUE(budget_id, user_id) );
CREATE TABLE budgets ( id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, name TEXT NOT NULL, category TEXT, amount REAL NOT NULL, spent REAL DEFAULT 0, period TEXT NOT NULL DEFAULT 'monthly', start_date TEXT NOT NULL, end_date TEXT, currency TEXT DEFAULT 'USD', notify_at_percent INTEGER DEFAULT 80, is_active BOOLEAN DEFAULT 1, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users (id) );
CREATE TABLE calendar_events ( id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, title TEXT NOT NULL, description TEXT, event_type TEXT NOT NULL, amount REAL, currency TEXT DEFAULT 'USD', event_date TEXT NOT NULL, end_date TEXT, is_recurring BOOLEAN DEFAULT 0, recurrence_rule TEXT, reminder_enabled BOOLEAN DEFAULT 1, reminder_days INTEGER DEFAULT 1, color TEXT DEFAULT '#5D5CDE', related_id INTEGER, related_type TEXT, is_completed BOOLEAN DEFAULT 0, completed_at DATETIME, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users (id) );
CREATE TABLE categories ( id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, name TEXT NOT NULL, type TEXT NOT NULL, color TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users (id), UNIQUE(user_id, name) );
CREATE TABLE currency_rates ( id INTEGER PRIMARY KEY AUTOINCREMENT, from_currency TEXT NOT NULL, to_currency TEXT NOT NULL, rate REAL NOT NULL, source TEXT DEFAULT 'manual', date TEXT NOT NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, UNIQUE(from_currency, to_currency, date) );
CREATE TABLE custom_banks ( id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, bank_key TEXT NOT NULL, name TEXT NOT NULL, country TEXT NOT NULL, api_url TEXT NOT NULL, auth_type TEXT NOT NULL DEFAULT 'api_key', scopes TEXT, endpoints TEXT, token_instructions TEXT, is_active BOOLEAN DEFAULT 1, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users (id), UNIQUE(user_id, bank_key) );
CREATE TABLE dashboard_widgets ( id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, widget_type TEXT NOT NULL, title TEXT, position INTEGER DEFAULT 0, size TEXT DEFAULT 'medium', settings TEXT, is_visible BOOLEAN DEFAULT 1, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users (id) );
CREATE TABLE debt_payments ( id INTEGER PRIMARY KEY AUTOINCREMENT, debt_id INTEGER NOT NULL, amount REAL NOT NULL, payment_type TEXT DEFAULT 'principal', note TEXT, transaction_id INTEGER, payment_date TEXT NOT NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (debt_id) REFERENCES debts (id) ON DELETE CASCADE, FOREIGN KEY (transaction_id) REFERENCES transactions (id) ON DELETE SET NULL );
CREATE TABLE debts ( id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, name TEXT NOT NULL, description TEXT, type TEXT NOT NULL, amount REAL NOT NULL, paid_amount REAL DEFAULT 0, interest_rate REAL DEFAULT 0, currency TEXT DEFAULT 'USD', counterparty TEXT, start_date TEXT NOT NULL, due_date TEXT, is_paid BOOLEAN DEFAULT 0, paid_at DATETIME, is_active BOOLEAN DEFAULT 1, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users (id) );
CREATE TABLE families ( id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, owner_id INTEGER NOT NULL, invite_code TEXT UNIQUE, description TEXT, is_active BOOLEAN DEFAULT 1, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (owner_id) REFERENCES users (id) );
CREATE TABLE family_invites ( id INTEGER PRIMARY KEY AUTOINCREMENT, family_id INTEGER NOT NULL, email TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'member', invite_token TEXT UNIQUE NOT NULL, expires_at DATETIME NOT NULL, used_at DATETIME, created_by INTEGER NOT NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (family_id) REFERENCES families (id) ON DELETE CASCADE, FOREIGN KEY (created_by) REFERENCES users (id) );
CREATE TABLE family_members ( id INTEGER PRIMARY KEY AUTOINCREMENT, family_id INTEGER NOT NULL, user_id INTEGER NOT NULL, role TEXT NOT NULL DEFAULT 'member', nickname TEXT, joined_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (family_id) REFERENCES families (id) ON DELETE CASCADE, FOREIGN KEY (user_id) REFERENCES users (id), UNIQUE(family_id, user_id) );
CREATE TABLE goal_contributions ( id INTEGER PRIMARY KEY AUTOINCREMENT, goal_id INTEGER NOT NULL, amount REAL NOT NULL, note TEXT, transaction_id INTEGER, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (goal_id) REFERENCES savings_goals (id) ON DELETE CASCADE, FOREIGN KEY (transaction_id) REFERENCES transactions (id) ON DELETE SET NULL );
CREATE TABLE investment_portfolios ( id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, name TEXT NOT NULL, description TEXT, currency TEXT DEFAULT 'USD', is_active BOOLEAN DEFAULT 1, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users (id) );
CREATE TABLE investment_prices ( id INTEGER PRIMARY KEY AUTOINCREMENT, symbol TEXT NOT NULL, price REAL NOT NULL, currency TEXT DEFAULT 'USD', date TEXT NOT NULL, source TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, UNIQUE(symbol, date) );
CREATE TABLE investment_transactions ( id INTEGER PRIMARY KEY AUTOINCREMENT, investment_id INTEGER NOT NULL, type TEXT NOT NULL, quantity REAL NOT NULL, price REAL NOT NULL, fee REAL DEFAULT 0, date TEXT NOT NULL, notes TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (investment_id) REFERENCES investments (id) ON DELETE CASCADE );
CREATE TABLE investments ( id INTEGER PRIMARY KEY AUTOINCREMENT, portfolio_id INTEGER NOT NULL, symbol TEXT NOT NULL, name TEXT NOT NULL, type TEXT NOT NULL, quantity REAL NOT NULL, buy_price REAL NOT NULL, current_price REAL, currency TEXT DEFAULT 'USD', buy_date TEXT NOT NULL, notes TEXT, is_active BOOLEAN DEFAULT 1, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (portfolio_id) REFERENCES investment_portfolios (id) ON DELETE CASCADE );
CREATE TABLE invites ( id INTEGER PRIMARY KEY AUTOINCREMENT, org_id INTEGER NOT NULL, email TEXT NOT NULL, token TEXT UNIQUE NOT NULL, role TEXT DEFAULT 'member', expires_at DATETIME NOT NULL, used_at DATETIME, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (org_id) REFERENCES organizations(id) ON DELETE CASCADE );
CREATE TABLE manual_assets ( id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, name TEXT NOT NULL, type TEXT NOT NULL, value REAL NOT NULL, currency TEXT DEFAULT 'USD', purchase_date TEXT, purchase_price REAL, description TEXT, is_active BOOLEAN DEFAULT 1, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users (id) );
CREATE TABLE networth_snapshots ( id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, total_assets REAL NOT NULL, total_liabilities REAL NOT NULL, net_worth REAL NOT NULL, assets_breakdown TEXT, liabilities_breakdown TEXT, snapshot_date TEXT NOT NULL, notes TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users (id) );
CREATE TABLE notification_settings ( id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL UNIQUE, budget_alerts BOOLEAN DEFAULT 1, recurring_reminders BOOLEAN DEFAULT 1, goal_milestones BOOLEAN DEFAULT 1, debt_reminders BOOLEAN DEFAULT 1, weekly_summary BOOLEAN DEFAULT 1, push_enabled BOOLEAN DEFAULT 0, email_enabled BOOLEAN DEFAULT 0, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users (id) );
CREATE TABLE notifications ( id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, type TEXT NOT NULL, title TEXT NOT NULL, message TEXT, data TEXT, is_read BOOLEAN DEFAULT 0, read_at DATETIME, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users (id) );
CREATE TABLE organization_members ( id INTEGER PRIMARY KEY AUTOINCREMENT, org_id INTEGER NOT NULL, user_id INTEGER NOT NULL, role TEXT DEFAULT 'member', created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (org_id) REFERENCES organizations(id) ON DELETE CASCADE, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE, UNIQUE(org_id, user_id) );
CREATE TABLE organizations ( id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, slug TEXT UNIQUE NOT NULL, plan TEXT DEFAULT 'free', ai_provider TEXT DEFAULT NULL, ai_model TEXT DEFAULT NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP );
CREATE TABLE receipts ( id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, image_path TEXT, image_data TEXT, merchant TEXT, total_amount REAL, currency TEXT DEFAULT 'USD', receipt_date TEXT, category TEXT, items TEXT, ocr_raw TEXT, ocr_status TEXT DEFAULT 'pending', transaction_id INTEGER, is_processed BOOLEAN DEFAULT 0, notes TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users (id), FOREIGN KEY (transaction_id) REFERENCES transactions (id) ON DELETE SET NULL );
CREATE TABLE recurring_payments ( id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, account_id INTEGER NOT NULL, name TEXT NOT NULL, description TEXT, amount REAL NOT NULL, type TEXT NOT NULL DEFAULT 'expense', category TEXT, frequency TEXT NOT NULL DEFAULT 'monthly', day_of_month INTEGER, day_of_week INTEGER, start_date TEXT NOT NULL, end_date TEXT, next_payment_date TEXT NOT NULL, last_payment_date TEXT, auto_create BOOLEAN DEFAULT 0, notify_before INTEGER DEFAULT 3, is_active BOOLEAN DEFAULT 1, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users (id), FOREIGN KEY (account_id) REFERENCES accounts (id) );
CREATE TABLE reports ( id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, report_type TEXT NOT NULL, title TEXT NOT NULL, period_start TEXT, period_end TEXT, file_path TEXT, file_data TEXT, format TEXT DEFAULT 'pdf', parameters TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users (id) );
CREATE TABLE savings_goals ( id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, name TEXT NOT NULL, description TEXT, target_amount REAL NOT NULL, current_amount REAL DEFAULT 0, currency TEXT DEFAULT 'USD', target_date TEXT, category TEXT, icon TEXT DEFAULT 'piggy-bank', color TEXT DEFAULT '#5D5CDE', is_completed BOOLEAN DEFAULT 0, completed_at DATETIME, is_active BOOLEAN DEFAULT 1, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users (id) );
CREATE TABLE split_expenses ( id INTEGER PRIMARY KEY AUTOINCREMENT, group_id INTEGER NOT NULL, paid_by INTEGER NOT NULL, description TEXT NOT NULL, amount REAL NOT NULL, split_type TEXT DEFAULT 'equal', date TEXT NOT NULL, category TEXT, is_settled BOOLEAN DEFAULT 0, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (group_id) REFERENCES split_groups (id) ON DELETE CASCADE, FOREIGN KEY (paid_by) REFERENCES split_members (id) );
CREATE TABLE split_groups ( id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, name TEXT NOT NULL, description TEXT, currency TEXT DEFAULT 'USD', is_active BOOLEAN DEFAULT 1, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users (id) );
CREATE TABLE split_members ( id INTEGER PRIMARY KEY AUTOINCREMENT, group_id INTEGER NOT NULL, user_id INTEGER, name TEXT NOT NULL, email TEXT, is_registered BOOLEAN DEFAULT 0, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (group_id) REFERENCES split_groups (id) ON DELETE CASCADE, FOREIGN KEY (user_id) REFERENCES users (id) );
CREATE TABLE split_settlements ( id INTEGER PRIMARY KEY AUTOINCREMENT, group_id INTEGER NOT NULL, from_member INTEGER NOT NULL, to_member INTEGER NOT NULL, amount REAL NOT NULL, date TEXT NOT NULL, note TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (group_id) REFERENCES split_groups (id) ON DELETE CASCADE, FOREIGN KEY (from_member) REFERENCES split_members (id), FOREIGN KEY (to_member) REFERENCES split_members (id) );
CREATE TABLE split_shares ( id INTEGER PRIMARY KEY AUTOINCREMENT, expense_id INTEGER NOT NULL, member_id INTEGER NOT NULL, amount REAL NOT NULL, is_paid BOOLEAN DEFAULT 0, paid_at DATETIME, FOREIGN KEY (expense_id) REFERENCES split_expenses (id) ON DELETE CASCADE, FOREIGN KEY (member_id) REFERENCES split_members (id) );
CREATE TABLE subscription_payments ( id INTEGER PRIMARY KEY AUTOINCREMENT, subscription_id INTEGER NOT NULL, amount REAL NOT NULL, payment_date TEXT NOT NULL, transaction_id INTEGER, status TEXT DEFAULT 'paid', created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (subscription_id) REFERENCES subscriptions (id) ON DELETE CASCADE, FOREIGN KEY (transaction_id) REFERENCES transactions (id) ON DELETE SET NULL );
CREATE TABLE subscriptions ( id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, name TEXT NOT NULL, description TEXT, amount REAL NOT NULL, currency TEXT DEFAULT 'USD', billing_cycle TEXT DEFAULT 'monthly', category TEXT, icon TEXT, color TEXT DEFAULT '#5D5CDE', start_date TEXT NOT NULL, next_billing_date TEXT, reminder_days INTEGER DEFAULT 3, is_active BOOLEAN DEFAULT 1, auto_renew BOOLEAN DEFAULT 1, account_id INTEGER, url TEXT, notes TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users (id), FOREIGN KEY (account_id) REFERENCES accounts (id) );
CREATE TABLE tags ( id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, name TEXT NOT NULL, color TEXT DEFAULT '#5D5CDE', created_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users (id), UNIQUE(user_id, name) );
CREATE TABLE transaction_tags ( transaction_id INTEGER NOT NULL, tag_id INTEGER NOT NULL, PRIMARY KEY (transaction_id, tag_id), FOREIGN KEY (transaction_id) REFERENCES transactions (id) ON DELETE CASCADE, FOREIGN KEY (tag_id) REFERENCES tags (id) ON DELETE CASCADE );
CREATE TABLE transactions ( id INTEGER PRIMARY KEY AUTOINCREMENT, account_id INTEGER NOT NULL, user_id INTEGER NOT NULL, date TEXT NOT NULL, description TEXT, category TEXT, amount REAL NOT NULL, type TEXT NOT NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (account_id) REFERENCES accounts (id), FOREIGN KEY (user_id) REFERENCES users (id) );
CREATE TABLE user_currency_settings ( id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL UNIQUE, base_currency TEXT NOT NULL DEFAULT 'USD', display_currencies TEXT DEFAULT '["UAH","USD","EUR"]', auto_convert BOOLEAN DEFAULT 0, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users (id) );
CREATE TABLE users ( id INTEGER PRIMARY KEY AUTOINCREMENT, username TEXT UNIQUE NOT NULL, email TEXT UNIQUE NOT NULL, password TEXT NOT NULL, full_name TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP , google_id TEXT, avatar_url TEXT, org_id INTEGER REFERENCES organizations(id));

CREATE INDEX idx_accounts_user ON accounts(user_id, is_active);
CREATE INDEX idx_ai_insights_lookup ON ai_insights(org_id, user_id, period, type);
CREATE INDEX idx_budgets_user ON budgets(user_id, is_active);
CREATE INDEX idx_calendar_events_user ON calendar_events(user_id, event_date);
CREATE INDEX idx_debts_user ON debts(user_id, is_active);
CREATE INDEX idx_goals_user ON savings_goals(user_id, is_active);
CREATE INDEX idx_notifications_user ON notifications(user_id, is_read, created_at DESC);
CREATE INDEX idx_recurring_user ON recurring_payments(user_id, is_active);
CREATE INDEX idx_sub_payments_sub ON subscription_payments(subscription_id, payment_date DESC);
CREATE INDEX idx_subscriptions_user ON subscriptions(user_id, is_active, next_billing_date);
CREATE INDEX idx_transactions_account ON transactions(account_id);
CREATE INDEX idx_transactions_user_category ON transactions(user_id, category);
CREATE INDEX idx_transactions_user_date ON transactions(user_id, date DESC);
CREATE INDEX idx_transactions_user_type ON transactions(user_id, type);
CREATE INDEX idx_transactions_user_type_date ON transactions(user_id, type, date);
CREATE UNIQUE INDEX idx_users_google_id ON users(google_id) WHERE google_id IS NOT NULL;
